package io.knowledgebrain.learning;
import java.util.*;
import java.io.IOException;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.web.server.ResponseStatusException;
import io.micrometer.core.instrument.MeterRegistry;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.DeserializationFeature;
import tools.jackson.core.StreamReadFeature;

@RestController
@ConditionalOnProperty(name="brain.learning.api.enabled",havingValue="true")
@RequestMapping("/api/spaces/{spaceId}/roadmaps")
final class RoadmapController {
 private final RoadmapStore store;private final SpaceAuthorizationClient authority;private final MeterRegistry metrics;private final String origin;
 private final JsonMapper json=JsonMapper.builder().enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 RoadmapController(RoadmapStore store,SpaceAuthorizationClient authority,MeterRegistry metrics,@Value("${brain.learning.browser-origin}")String origin){this.store=store;this.authority=authority;this.metrics=metrics;this.origin=origin;}
 static String tag(long version){return "\"rm"+version+"\"";}
 static long version(HttpServletRequest r){var values=Collections.list(r.getHeaders("If-Match"));if(values.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(values.size()!=1||!values.getFirst().matches("\"rm[1-9][0-9]{0,18}\""))throw RoadmapGraph.bad();try{return Long.parseLong(values.getFirst().substring(3,values.getFirst().length()-1));}catch(NumberFormatException e){throw RoadmapGraph.bad();}}
 static void parameters(HttpServletRequest r,Set<String> allowed){for(var p:r.getParameterMap().entrySet())if(!allowed.contains(p.getKey())||p.getValue().length!=1)throw RoadmapGraph.bad();if(r.getMethod().equals("GET")&&(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null))throw RoadmapGraph.bad();}
 static long number(String raw,long fallback,long max){if(raw==null)return fallback;if(!raw.matches("[1-9][0-9]{0,18}"))throw RoadmapGraph.bad();try{long value=Long.parseLong(raw);if(value>max)throw RoadmapGraph.bad();return value;}catch(NumberFormatException e){throw RoadmapGraph.bad();}}
 static String parent(HttpServletRequest r){var headers=Collections.list(r.getHeaders("traceparent"));if(headers.size()==1){String p=headers.getFirst();if(p.matches("00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}")&&!p.substring(3,35).equals("0".repeat(32))&&!p.substring(36,52).equals("0".repeat(16)))return p;}return "00-"+UUID.randomUUID().toString().replace("-","")+"-"+UUID.randomUUID().toString().replace("-","").substring(0,16)+"-01";}
 UUID authorize(UUID space,HttpServletRequest r,boolean write,String trace){if(!r.isSecure())throw RoadmapGraph.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credential required");token=c.getValue();}return authority.authorize(space,token,write,trace);}
 UUID authorizeGithub(UUID space,HttpServletRequest r,boolean write,String trace){UUID actor=authorize(space,r,write,trace);String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest"))token=c.getValue();UUID restricted=authority.authorize(space,token,write?"GITHUB_EVIDENCE_WRITE":"GITHUB_EVIDENCE_READ","PRIVATE",trace);if(!actor.equals(restricted))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Principal changed");return actor;}
 tools.jackson.databind.JsonNode body(HttpServletRequest r,int cap)throws IOException{if(!MediaType.APPLICATION_JSON_VALUE.equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"JSON required");byte[] bytes=r.getInputStream().readNBytes(cap+1);if(bytes.length>cap)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Roadmap request too large");try{var value=json.readTree(bytes);if(value==null||!value.isObject())throw RoadmapGraph.bad();return value;}catch(RuntimeException e){throw RoadmapGraph.bad();}}
 private String[] edit(HttpServletRequest r)throws IOException{var value=body(r,262144);if(value.size()!=2||!value.path("title").isString()||!value.path("description").isString())throw RoadmapGraph.bad();return new String[]{value.path("title").asString(),value.path("description").asString()};}
 private RoadmapGraph.Edit graph(HttpServletRequest r)throws IOException{var value=body(r,1048576);if(value.size()!=2||!value.path("nodes").isArray()||!value.path("edges").isArray()||value.path("nodes").size()>100||value.path("edges").size()>500)throw RoadmapGraph.bad();var nodes=new ArrayList<RoadmapGraph.NodeEdit>();var edges=new ArrayList<RoadmapGraph.EdgeEdit>();for(var n:value.path("nodes")){if(!n.isObject()||n.size()!=3||!n.path("key").isString()||!n.path("title").isString()||!n.path("description").isString())throw RoadmapGraph.bad();nodes.add(new RoadmapGraph.NodeEdit(n.path("key").asString(),n.path("title").asString(),n.path("description").asString()));}for(var e:value.path("edges")){if(!e.isObject()||e.size()!=4||!e.path("key").isString()||!e.path("kind").isString()||!e.path("source").isString()||!e.path("target").isString())throw RoadmapGraph.bad();edges.add(new RoadmapGraph.EdgeEdit(e.path("key").asString(),e.path("kind").asString(),e.path("source").asString(),e.path("target").asString()));}return new RoadmapGraph.Edit(nodes,edges);}
 private ResponseEntity<RoadmapStore.Roadmap> response(RoadmapStore.Roadmap value){return ResponseEntity.ok().eTag(tag(value.version())).cacheControl(CacheControl.noStore()).body(value);}
 @PostMapping ResponseEntity<RoadmapStore.Roadmap> create(@PathVariable String spaceId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);String trace=parent(r);UUID actor=authorize(space,r,true,trace);var edit=edit(r);var value=store.create(space,actor,edit[0],edit[1],trace.substring(3,35));metrics.counter("brain.learning.roadmap.changes","type","created").increment();return ResponseEntity.status(201).header("Location","/api/spaces/"+space+"/roadmaps/"+value.roadmapId()).eTag(tag(value.version())).cacheControl(CacheControl.noStore()).body(value);}
 @GetMapping ResponseEntity<RoadmapStore.Page> list(@PathVariable String spaceId,HttpServletRequest r){parameters(r,Set.of("after","limit"));var space=RoadmapGraph.id(spaceId);UUID after=r.getParameter("after")==null?null:RoadmapGraph.id(r.getParameter("after"));int limit=(int)number(r.getParameter("limit"),20,100);authorize(space,r,false,parent(r));metrics.counter("brain.learning.roadmap.reads","type","catalog").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.list(space,after,limit));}
 @GetMapping("/{roadmapId}") ResponseEntity<RoadmapStore.Roadmap> get(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);authorize(space,r,false,parent(r));metrics.counter("brain.learning.roadmap.reads","type","current").increment();return response(store.get(space,id));}
 @PutMapping("/{roadmapId}") ResponseEntity<RoadmapStore.Roadmap> metadata(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);String trace=parent(r);UUID actor=authorize(space,r,true,trace);long version=version(r);var edit=edit(r);var value=store.metadata(space,id,actor,version,edit[0],edit[1],false,trace.substring(3,35));metrics.counter("brain.learning.roadmap.changes","type","metadata").increment();return response(value);}
 @PutMapping("/{roadmapId}/graph") ResponseEntity<RoadmapStore.Roadmap> graph(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);String trace=parent(r);UUID actor=authorize(space,r,true,trace);long version=version(r);var edit=graph(r);var value=store.graph(space,id,actor,version,edit,trace.substring(3,35));metrics.counter("brain.learning.roadmap.changes","type","graph").increment();return response(value);}
 @DeleteMapping("/{roadmapId}") ResponseEntity<Void> retire(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){parameters(r,Set.of());if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw RoadmapGraph.bad();var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);String trace=parent(r);UUID actor=authorize(space,r,true,trace);var value=store.metadata(space,id,actor,version(r),null,null,true,trace.substring(3,35));metrics.counter("brain.learning.roadmap.changes","type","retired").increment();return ResponseEntity.noContent().eTag(tag(value.version())).cacheControl(CacheControl.noStore()).build();}
 @GetMapping("/{roadmapId}/revisions") ResponseEntity<List<RoadmapStore.Revision>> history(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){parameters(r,Set.of("before","limit"));var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);long before=number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)number(r.getParameter("limit"),5,10);authorize(space,r,false,parent(r));metrics.counter("brain.learning.roadmap.reads","type","history").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(space,id,before,limit));}
}
